import { describe, expect, it } from 'vitest';
import { crc16, decodeEq, encodeEq, presetBase } from '../src/hardware/codec';
import { PanelSession, type Backup } from '../src/hardware/session';
import { SimulatedPanel } from '../src/hardware/simulator';

// Synthetic independent native-layout page, not generated by encodeEq and not
// a GUI/device capture. Metadata layout is HFD ab0dbc; fallback tables are
// d3bbcc..d3bbec. Compiled response intentionally differs from the metadata.
const centers = [50, 100, 200, 500, 1000, 2000, 5000, 10000, 16000];
const compiled = [1048576, 2097152, 16777216, -2097152, 4194304]; // b2,b1,b0,f2,f1
function seal(page: Uint8Array) {
  new DataView(page.buffer, page.byteOffset, page.byteLength).setUint16(
    254,
    crc16(page.subarray(0, 254)),
    true,
  );
  return page;
}
function fixture() {
  const page = new Uint8Array(256).fill(255),
    view = new DataView(page.buffer);
  for (let i = 0; i < 9; i++) {
    compiled.forEach((word, j) => view.setInt32(i * 20 + j * 4, word, true));
    const offset = 180 + i * 8,
      frequency = 123456 + i;
    page[offset] = 128 | (i % 3);
    page[offset + 1] = frequency & 255;
    page[offset + 2] = (frequency >> 8) & 255;
    page[offset + 3] = frequency >> 16;
    view.setUint16(offset + 4, 1234 + i, true);
    view.setInt16(offset + 6, -2500 + i, true);
  }
  return seal(page);
}
function sameWithoutId(band: ReturnType<typeof decodeEq>[number]) {
  const { id: _id, ...rest } = band;
  return rest;
}

describe('initialized native EQ zero-metadata interpretation', () => {
  it.each(centers.map((center, index) => ({ center, index })))(
    'uses native center$center only for band$index zero frequency, retaining coefficients and other metadata',
    ({ center, index }) => {
      const page = fixture(),
        offset = 180 + index * 8;
      page.fill(0, offset + 1, offset + 4);
      seal(page);
      const original = page.slice(),
        bands = decodeEq(page),
        band = bands[index];
      expect(band.frequency).toBe(center);
      expect(band.q).toBe((1234 + index) / 1000);
      expect(band.gain).toBe((-2500 + index) / 1000);
      expect(band.enabled).toBe(true);
      expect(band.kind).toBe(['peak', 'lowshelf2', 'highshelf2'][index % 3]);
      expect(band.coefficients).toEqual({ b2: 0.0625, b1: 0.125, b0: 1, f2: -0.125, f1: 0.25 });
      expect(band.provenance).toBe('panel');
      expect(page).toEqual(original);
      for (let other = 0; other < 9; other++)
        if (other !== index) expect(bands[other].frequency).toBe((123456 + other) / 100);
    },
  );

  it.each(Array.from({ length: 9 }, (_, index) => index))(
    'uses native Q0.707 only for band%s zero Q, preserving nonzero frequency/gain/type',
    (index) => {
      const page = fixture(),
        view = new DataView(page.buffer),
        offset = 180 + index * 8;
      view.setUint16(offset + 4, 0, true);
      seal(page);
      const band = decodeEq(page)[index];
      expect(band.q).toBe(0.707);
      expect(band.frequency).toBe((123456 + index) / 100);
      expect(band.gain).toBe((-2500 + index) / 1000);
      expect(band.coefficients).toEqual({ b2: 0.0625, b1: 0.125, b0: 1, f2: -0.125, f1: 0.25 });
      expect(band.provenance).toBe('panel');
    },
  );

  it('does not normalize tiny/nonzero metadata or negative gain and retains erased/CRC/type guards', () => {
    const page = fixture(),
      view = new DataView(page.buffer);
    page.set([1, 0, 0], 181);
    view.setUint16(184, 1, true);
    view.setInt16(186, -32768, true);
    seal(page);
    expect(decodeEq(page)[0]).toMatchObject({ frequency: 0.01, q: 0.001, gain: -32.768 });
    for (const value of [0, 255]) {
      const erased = decodeEq(new Uint8Array(256).fill(value));
      expect(erased.map((band) => band.frequency)).toEqual(centers);
      expect(
        erased.every(
          (band) => !band.enabled && band.q === 0.707 && band.gain === 0 && !band.coefficients,
        ),
      ).toBe(true);
    }
    const corrupt = page.slice();
    corrupt[254] ^= 1;
    expect(() => decodeEq(corrupt)).toThrow('CRC');
    const unsupported = page.slice();
    unsupported[180] = 135;
    seal(unsupported);
    expect(() => decodeEq(unsupported)).toThrow('metadata type');
    expect(() => decodeEq(page.subarray(0, 255))).toThrow('Incomplete');
  });

  it('interprets a byte-offset page and canonically re-encodes fallback metadata without redesigning compiled coefficients', () => {
    const page = fixture();
    for (let i = 0; i < 9; i++) page.fill(0, 181 + i * 8, 186 + i * 8);
    seal(page);
    const padded = new Uint8Array(300);
    padded.set(page, 7);
    const bands = decodeEq(padded.subarray(7, 263)),
      encoded = encodeEq(bands);
    expect(bands.map((band) => band.frequency)).toEqual(centers);
    expect(bands.every((band) => band.q === 0.707 && band.provenance === 'panel')).toBe(true);
    expect(encoded.subarray(0, 180)).toEqual(page.subarray(0, 180));
    expect(decodeEq(encoded).map(sameWithoutId)).toEqual(bands.map(sameWithoutId));
    expect(padded.subarray(7, 263)).toEqual(page);
    const values = new DataView(encoded.buffer);
    for (let i = 0; i < 9; i++) {
      const offset = 180 + i * 8;
      expect(encoded[offset + 1] | (encoded[offset + 2] << 8) | (encoded[offset + 3] << 16)).toBe(
        centers[i] * 100,
      );
      expect(values.getUint16(offset + 4, true)).toBe(707);
    }
  });

  it('keeps original zero metadata in exact recovery backups while an explicit simulated EQ upload writes interpreted defaults and original coefficients', async () => {
    const panel = new SimulatedPanel('EQ-FALLBACK'),
      saved: Backup[] = [];
    const session = new PanelSession(panel, async (backup) => {
      saved.push(structuredClone(backup));
    });
    const page = fixture();
    for (let i = 0; i < 9; i++) page.fill(0, 181 + i * 8, 186 + i * 8);
    seal(page);
    const base = presetBase(1) + 0x3000,
      original = panel.memory.slice(base, base + 4096);
    original.set(page);
    panel.memory.set(original, base);
    const read = await session.readEq(1);
    expect(
      panel.requests.filter(
        (request) => (request[0] === 5 && request[1] === 0) || request[0] === 0x64,
      ),
    ).toHaveLength(0);
    expect(Buffer.from(read.backup.sector_hex, 'hex')).toEqual(Buffer.from(original));
    expect(read.bands.map((band) => band.frequency)).toEqual(centers);
    await session.uploadEq(1, read.bands, true);
    const uploaded = panel.memory.slice(base, base + 4096);
    expect(uploaded.slice(0, 180)).toEqual(original.slice(0, 180));
    expect(uploaded.slice(256)).toEqual(original.slice(256));
    expect(decodeEq(uploaded).map(sameWithoutId)).toEqual(read.bands.map(sameWithoutId));
    expect(
      saved.every((backup) => backup.sector_hex === Buffer.from(original).toString('hex')),
    ).toBe(true);
    expect(saved).toHaveLength(2);
  }, 10000);
});
